// The CURATED EDGE-CASE SUITE of the gun models: a handful of builds per platform, generated by RULES from the parts data (G.Gunsmith:
// slotsOf / compatible / fitsSlot / prune / defaultBuild, the fit rule fitsLen with a build), so a new gun or part gets its cases without anyone
// writing them. Used by the baker (tools/bake_parts.mjs adds them to every platform's analysis) and by the test (tools/check_model_cases.mjs).
//
//   node tools/model_cases.mjs                 prints the cases per platform and checks tests/model-builds.json is current
//   node tools/model_cases.mjs --write         rewrites tests/model-builds.json (the committed, readable list: platform, why, build)
//   node tools/model_cases.mjs --sheet <dir>   renders every case (side view, assembled from the packs, labelled with its why) as one page per gun
//   node tools/model_cases.mjs --only m4,ak    just those platforms
//
// THE RULES (docs/models.md "Testing"). Per platform:
//   default        the factory build
//   bare           every optional slot empty
//   loaded         every slot filled with its first part (both tac rails, a foregrip, a red dot and a magnifier where they fit); loaded-last: the same with the LAST part of each slot
//   barrels        the shortest barrel with the longest handguard that fits it; the longest barrel with the shortest handguard
//   openers        every part that OPENS slots (railmounts, buttstock adapters, riser dots, chassis, barrels that give a handguard mount ...), fitted, with the slots it opens filled
//   sight stack    the lowest and the tallest optic alone; a magnifier behind the lowest and behind the tallest optic that takes one
//   pistols        each slide x each grip (the pistol chassis among them), each with a red dot
//   specials       integral suppressors (barrels with the can built in), the biggest magazine and a drum, a bipod, a suppressor on the muzzle
// Dedupe by build; a build two rules give carries both labels.
import fs from 'fs'; import path from 'path'; import { pathToFileURL } from 'url';
import { ROOT } from './model_env.mjs';

export const CASES_FILE = path.join(ROOT, 'tests/model-builds.json');
export const REGRESSIONS_FILE = path.join(ROOT, 'tests/model-regressions.json');

/** A stable text key of a build (slot=part pairs, sorted). */
export const keyOf = (b) => Object.keys(b).sort().map((s) => s + '=' + b[s]).join(',');

/** Optic height, roughly: the order the sight stack's extremes are picked by (lowest = irons, tallest = a long variable scope on a riser). */
const OPTIC_H = { none: 0, irons: 0, notch: 0, bead: 0, night: 0.5, qbzirons: 1, augscope: 3, minidot: 1, reddot: 2, holo: 2.5, riser: 2, prism: 3, acog: 4, lpvo: 5, scope: 6 };
const opticHeight = (p) => { const m = (p.model || {}), o = m.was || m.optic; if (p.authored) return { low: 1.5, mid: 2.8, high: 4.5 }[p.authored.height] ?? 3; return (OPTIC_H[o] ?? 3) + (m.riser || 0) * 20 + (m.dotR || 0) * 10 + (m.scopeObj || 0) * 10; };

export function generate(G, id) {
  const GS = G.Gunsmith, PARTS = GS.PARTS, out = [], index = new Map();
  const add = (why, build) => {
    const b = { ...build }; GS.prune(id, b);
    const k = keyOf(b), had = index.get(k);
    if (had) { if (!had.why.split(' + ').includes(why)) had.why += ' + ' + why; return; }
    const c = { platform: id, why, build: Object.fromEntries(Object.keys(b).sort().map((s) => [s, b[s]])) }; index.set(k, c); out.push(c);
  };
  const live = (p) => !!p && !p.retired && !p.variant;
  const slots = (b) => GS.slotsOf(id, b);
  const options = (s, b) => GS.compatible(s.mount).filter((p) => live(p) && GS.fitsSlot(s, p, id, b));
  const slotOf = (b, name) => slots(b).find((s) => s.slot === name);
  const kindIs = (s, ...ks) => ks.includes(s.slot.replace(/\d+$/, ''));
  const def = GS.defaultBuild(id);
  const isReflex = (p) => !!(p.provides && p.provides.magnifier);

  /** Every empty slot filled (passes: a part opens slots), `pick(options, slot)` choosing the part; optics keep a reflex sight where one fits (a magnifier needs one). */
  const fill = (base, pick, { magnifier = true } = {}) => {
    let b = { ...base };
    for (let pass = 0; pass < 4; pass++) for (const s of slots(b)) {
      if (b[s.slot]) continue;
      if (kindIs(s, 'magnifier') && !magnifier) continue;
      let c = options(s, b);
      if (kindIs(s, 'optic')) { const r = c.filter(isReflex); if (r.length) c = r; }
      const p = pick(c, s); if (p) { b[s.slot] = p.id; GS.prune(id, b); }
    }
    return b;
  };
  const first = (c) => c[0], last = (c) => c[c.length - 1];
  const bare = (base) => { const b = { ...base }; for (let again = true; again;) { again = false; for (const s of slots(b)) if (!s.req && b[s.slot]) { delete b[s.slot]; again = true; } GS.prune(id, b); } return b; };

  add('default', def);
  add('bare', bare(def));
  const loaded = fill(def, first), loadedLast = fill(def, last);
  add('loaded', loaded); add('loaded-last', loadedLast);

  // barrel x handguard extremes
  const bs = slotOf(def, 'barrel'), hs = slotOf(def, 'handguard');
  if (bs && hs) {
    const len = (p) => GS.barrelOf(p, id) ?? 0, hlen = (p) => (p.model && p.model.hg && p.model.hg.len) ?? 0;
    const barrels = GS.compatible(bs.mount).filter((p) => live(p) && GS.fitsSlot(bs, p, id, def)).sort((a, b) => len(a) - len(b));
    const hgOn = (br) => { const b = { ...def, barrel: br.id }; GS.prune(id, b); const s = slotOf(b, 'handguard'); return s ? options(s, b).sort((a, c) => hlen(a) - hlen(c)) : []; };
    if (barrels.length > 1) {
      const lo = barrels[0], hi = barrels[barrels.length - 1], a = hgOn(lo), c = hgOn(hi);
      if (a.length) add(`shortest barrel (${lo.id}) x longest handguard that fits (${a[a.length - 1].id})`, { ...def, barrel: lo.id, handguard: a[a.length - 1].id });
      if (c.length) add(`longest barrel (${hi.id}) x shortest handguard (${c[0].id})`, { ...def, barrel: hi.id, handguard: c[0].id });
    }
  }

  // slot-opening parts, with the slots they open filled
  const bases = [def];
  for (const base of bases) for (const s of slots(base)) for (const p of options(s, base)) {
    if (!(p.provides || p.chassis) || base[s.slot] === p.id) continue;
    const b1 = { ...base, [s.slot]: p.id }; GS.prune(id, b1); if (b1[s.slot] !== p.id) continue;
    const before = new Set(slots(base).map((x) => x.slot)), opened = slots(b1).filter((x) => !before.has(x.slot) || (p.chassis && p.chassis[x.slot]));
    if (!opened.length || opened.every((x) => x.slot === 'magnifier')) continue; // (a sight that takes a magnifier: the sight-stack rule has the extremes)
    let b = b1;
    for (let pass = 0; pass < 3; pass++) for (const o of slots(b)) { if (b[o.slot] || (before.has(o.slot) && !(p.chassis && p.chassis[o.slot]))) continue; const c = options(o, b); const q = kindIs(o, 'optic', 'riserdot') ? (c.filter(isReflex)[0] || c[0]) : c[0]; if (q) { b = { ...b, [o.slot]: q.id }; GS.prune(id, b); } }
    add(`opens slots: ${p.id} in ${s.slot} (${opened.map((x) => x.slot).join(', ')})`, b);
  }

  // the sight stack
  const os = slotOf(loaded, 'optic') || slotOf(def, 'optic');
  if (os) {
    const withOptics = options(os, loaded).sort((a, b) => opticHeight(a) - opticHeight(b) || (a.idx - b.idx));
    if (withOptics.length) {
      const lo = withOptics[0], hi = withOptics[withOptics.length - 1];
      const noMag = (o) => { const b = { ...loaded, optic: o.id }; delete b.magnifier; GS.prune(id, b); return b; };
      add(`lowest optic (${lo.id})`, noMag(lo)); if (hi !== lo) add(`tallest optic (${hi.id})`, noMag(hi));
      const rx = withOptics.filter(isReflex);
      for (const [name, o] of [['lowest', rx[0]], ['tallest', rx[rx.length - 1]]]) {
        if (!o) continue;
        const b = noMag(o), ms = slotOf(b, 'magnifier'); if (!ms) continue;
        const m = options(ms, b)[0]; if (m) add(`magnifier on the ${name} optic that takes one (${o.id})`, { ...b, magnifier: m.id });
      }
    }
  }

  // pistols: each slide x each grip, a red dot
  const ss = slotOf(def, 'slide');
  if (ss) {
    const gs = slotOf(def, 'grip');
    const slides = options(ss, def), grips = gs ? options(gs, def) : [null];
    const dotOn = (b) => { const s = slotOf(b, 'optic'); if (!s) return b; const c = options(s, b), d = c.find((p) => p.model && ['minidot', 'reddot'].includes(p.model.was || p.model.optic)) || c[0]; return d ? { ...b, optic: d.id } : b; };
    // (not the full cross, which is ~50 builds a gun: each slide on the gun's own grip and on the pistol chassis, each grip under the gun's own slide)
    const chassis = grips.filter((g) => g && g.chassis), own = def.grip ? PARTS[def.grip] : null;
    const pairs = [...slides.flatMap((sl) => [[sl, own], ...chassis.map((g) => [sl, g])]), ...grips.map((g) => [PARTS[def.slide] || slides[0], g])];
    for (const [sl, g] of pairs) {
      let b = { ...def, slide: sl.id }; if (g) b.grip = g.id; GS.prune(id, b);
      if (g && g.chassis) { delete b.optic; b = fill(b, first); } else b = dotOn(b); // (on the chassis: everything it opens filled, a magnifier behind a reflex sight too)
      add(`pistol: slide ${sl.id} x grip ${g ? g.id : '-'} ${g && g.chassis ? 'fully loaded' : 'with a red dot'}`, b);
    }
  }

  // the entries an authored part replaces the model of, on a riser (the riser is the gun's mount piece, the part the same file as on a pistol's slide)
  { const os = slotOf(def, 'optic'); const rz = os && options(os, def).find((p) => p.model && p.model.optic === 'riser'); if (rz) {
    const b = { ...def, optic: rz.id }; delete b.magnifier; GS.prune(id, b); const rs = slotOf(b, 'riserdot'), q = rs && options(rs, b).find((p) => p.model && p.model.was);
    if (q) { add(`replaced optic (${q.id}) on the riser`, { ...b, riserdot: q.id }); const ms = slotOf({ ...b, riserdot: q.id }, 'magnifier'), m = ms && options(ms, { ...b, riserdot: q.id })[0]; if (m) add(`magnifier behind the replaced optic (${q.id}) on the riser`, { ...b, riserdot: q.id, magnifier: m.id }); }
  } }
  // authored parts (models/parts): each one fitted alone where it fits, and a magnifier behind it where it takes one
  { const os = slotOf(def, 'optic'); if (os) for (const p of options(os, def)) if (p.id.startsWith('op.auth.') || (p.model && p.model.was)) { // (and the entries an authored part REPLACES the model of)
    const b = { ...def, optic: p.id }; delete b.magnifier; GS.prune(id, b); add(`authored optic (${p.id})`, b);
    if (p.provides && p.provides.magnifier) { const ms = slotOf(b, 'magnifier'); const m = ms && options(ms, b)[0]; if (m) add(`magnifier behind the authored optic (${p.id})`, { ...b, magnifier: m.id }); }
  } }
  // specials
  const brs = slotOf(def, 'barrel');
  if (brs) for (const p of options(brs, def)) if (p.model && p.model.integral) add(`integral suppressor (${p.id})`, { ...loaded, barrel: p.id });
  const ms2 = slotOf(def, 'mag');
  if (ms2) {
    const mags = options(ms2, def), cap = (p) => (p.set && p.set.cap) || 0, drum = (p) => !!(p.model && p.model.mag && p.model.mag.t === 'drum');
    const big = [...mags].sort((a, b) => cap(b) - cap(a))[0], dr = mags.filter(drum).sort((a, b) => cap(b) - cap(a))[0], small = [...mags].sort((a, b) => cap(a) - cap(b))[0];
    if (big && big.id !== def.mag) add(`biggest magazine (${big.id})`, { ...def, mag: big.id });
    if (dr && dr.id !== def.mag && dr !== big) add(`drum magazine (${dr.id})`, { ...def, mag: dr.id });
    if (small && small.id !== def.mag && mags.length > 2) add(`smallest magazine (${small.id})`, { ...def, mag: small.id });
  }
  for (const b0 of [loaded]) { const fs2 = slotOf(b0, 'fg'); if (fs2) { const bip = options(fs2, b0).find((p) => p.model && p.model.fg === 'bipod'); if (bip) add(`bipod (${bip.id})`, { ...b0, fg: bip.id }); } }
  { const mz = slotOf(loaded, 'muzzle'); if (mz) { const sup = options(mz, loaded).find((p) => p.set && p.set.sup); if (sup) add(`suppressor on the muzzle (${sup.id})`, { ...loaded, muzzle: sup.id }); } }
  return out;
}

/** The platforms in game order. */
export const platformsOf = (G, only) => Object.keys(G.Gunsmith.PLATFORMS).filter((id) => G.WEAPONS[id] && (!only || only.includes(id)));

/** Every generated case, all platforms (or `only`). */
export function generateAll(G, only) { return platformsOf(G, only).flatMap((id) => generate(G, id)); }

/**
 * The hand-maintained regressions (tests/model-regressions.json), as { platform, why, build }. A build is checked against the current parts: a part id that no
 * longer exists, or a build the gunsmith would prune, comes back in `stale` (the test fails on it: map it to the current equivalent in the file).
 */
export function regressionsOf(G, only) {
  const GS = G.Gunsmith, raw = fs.existsSync(REGRESSIONS_FILE) ? JSON.parse(fs.readFileSync(REGRESSIONS_FILE, 'utf8')) : { cases: [] };
  const cases = [], stale = [];
  for (const c of raw.cases) {
    if (only && !only.includes(c.platform)) continue;
    const missing = Object.values(c.build).filter((p) => !GS.PARTS[p]);
    const b = { ...c.build }; if (!missing.length && GS.PLATFORMS[c.platform]) GS.prune(c.platform, b);
    if (missing.length) stale.push(`${c.platform} "${c.why}": no such part ${missing.join(', ')}`);
    else if (keyOf(b) !== keyOf(c.build)) stale.push(`${c.platform} "${c.why}": the build is not valid any more (the gunsmith drops ${Object.keys(c.build).filter((s) => b[s] !== c.build[s]).map((s) => s + '=' + c.build[s]).join(', ')})`);
    cases.push({ platform: c.platform, why: 'regression: ' + c.why, build: missing.length ? c.build : b, regression: true });
  }
  return { cases, stale };
}

/** Whether the committed tests/model-builds.json is what the rules give now. */
export function committedCases() { return fs.existsSync(CASES_FILE) ? JSON.parse(fs.readFileSync(CASES_FILE, 'utf8')) : null; }
export const casesText = (cases) => JSON.stringify({ about: 'Generated by tools/model_cases.mjs --write from the parts data (rules in docs/models.md, Testing). Do not edit by hand: add hand-made cases to model-regressions.json.', cases }, null, 1).replace(/\{\n\s+"platform"/g, '{ "platform"').replace(/"build": \{\n([^}]*)\}/g, (m, body) => '"build": { ' + body.replace(/\n\s*/g, ' ').trim() + ' }');

// ---------------------------------------------------------------------------------------------------------------- CLI
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const { loadGame } = await import('./model_env.mjs');
  const args = process.argv.slice(2), opt = (k) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : null; };
  const only = opt('--only') ? opt('--only').split(',') : null, G = loadGame();
  const cases = generateAll(G, only);
  const per = {}; for (const c of cases) per[c.platform] = (per[c.platform] || 0) + 1;
  if (args.includes('--write')) {
    if (only) { console.error('--write takes every platform (no --only)'); process.exit(1); }
    fs.mkdirSync(path.dirname(CASES_FILE), { recursive: true }); fs.writeFileSync(CASES_FILE, casesText(cases) + '\n');
    console.log(`wrote ${cases.length} cases for ${Object.keys(per).length} platforms to ${path.relative(ROOT, CASES_FILE)}`);
  } else if (!opt('--sheet')) {
    for (const [id, n] of Object.entries(per)) { console.log(id.padEnd(10), n); if (args.includes('--list')) for (const c of cases.filter((x) => x.platform === id)) console.log('   ', c.why); }
    console.log(`total ${cases.length} cases, ${Object.keys(per).length} platforms, min ${Math.min(...Object.values(per))}, max ${Math.max(...Object.values(per))}, mean ${(cases.length / Object.keys(per).length).toFixed(1)}`);
    if (!only) { const c = committedCases(); const same = c && JSON.stringify(c.cases) === JSON.stringify(JSON.parse(JSON.stringify(cases))); console.log(same ? 'tests/model-builds.json is current' : 'tests/model-builds.json is OUT OF DATE: run node tools/model_cases.mjs --write'); process.exitCode = same ? 0 : 1; }
  }
  if (opt('--sheet')) await (await import('./model_sheet.mjs')).sheets(G, cases, regressionsOf(G, only).cases, opt('--sheet'));
}
